/* All export and job content is escaped before rendering. No external scripts. */
let state, view='jobs', activeJob, draftData, pollTimer, jobPage=1;
const $=s=>document.querySelector(s);
let sourceExposureTimer;function recordVisibleSources(){clearTimeout(sourceExposureTimer);sourceExposureTimer=setTimeout(()=>{const ids=new Set([...document.querySelectorAll('#job-list [data-job]')].map(b=>b.dataset.job));for(const job_id of ids)api('/api/source-events',{job_id,kind:'shown'}).catch(()=>{});},500);}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeLink=url=>{try{const u=new URL(url);return /^https?:$/.test(u.protocol)&&!u.username&&!u.password?u.href:''}catch{return ''}};
const link=(url,label,cls='')=>`<a class="${cls}" href="${esc(safeLink(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
const pill=(text,type='')=>`<span class="pill ${type}">${esc(text)}</span>`;
const statusOptions=selected=>state.statuses.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
async function api(path,body){if(window.workspaceAPI)return window.workspaceAPI(path,body);const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Token':state?.token||''},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function message(text,error=false){const el=$('#message');el.hidden=false;el.textContent=text;el.className=error?'error':''}
async function load(){captureBoardContext();state=await api('/api/bootstrap');await prepareResearchReviews();$('#loading').hidden=true;$('#content').hidden=false;$('#storage-label').textContent=state.storage_mode==='browser'?'Private in this browser':'Private on this computer';$('#sidebar-name').textContent=state.profile.name||'Your workspace';$('#sidebar-context').textContent=state.profile.preferences?.visa?state.profile.preferences.visa+' · '+(state.profile.education?.graduation||'Confirm graduation'):'Import a profile to personalize';$('#nav-count').textContent=state.jobs.filter(j=>j.screen.eligible&&!j.closed&&!['Applied','Interview','Offer','Rejected','Archived'].includes(j.status)&&!isFang(j)&&visaEvidence(j).status==='confirmed').length;$('#nav-discovery-count').textContent=state.jobs.filter(j=>j.screen.eligible&&!j.closed&&!['Applied','Interview','Offer','Rejected','Archived'].includes(j.status)&&j.source_feedback!=='not_interested'&&j.screen.role_family!=='unverified'&&!isFang(j)).length;$('#nav-fang-count').textContent=state.jobs.filter(j=>j.screen.eligible&&!j.closed&&!['Applied','Interview','Offer','Rejected','Archived'].includes(j.status)&&j.source_feedback!=='not_interested'&&isFang(j)).length;render()}
const meta={actions:['YOUR NEXT APPLICATION STEP','Next actions.','Due reminders, captured application cutoffs and the next preparation step for your selected and verified roles.'],discovery:['BROWSE REAL DISCOVERY LEADS','Browse other jobs and connections.','Board/source-reported non-FANG engineering leads. Use the visa details stated by the listing; missing details say Check with employer. Report incorrect information on any role. Open FANG for Amazon, Meta, Netflix and Google. Employer visa policy and role fit remain separate checks; incomplete descriptions are labeled.'],verification:['CHECK ROLE-SPECIFIC ELIGIBILITY','Check OPT.','Check initial OPT acceptance for each exact posting. Future H-1B is optional. Unknown, conditional and disputed policies stay here.'],jobs:['ROLE-SPECIFIC OPT INFORMATION','OPT accepted.','The posting or job board explicitly states initial OPT acceptance. Future H-1B sponsorship is optional. Your authorization, role fit, start date and deadline still require review.'],prepare:['MAKE ROOM FOR PREPARATION','FANG: prepare, then apply.','Potential Amazon, Meta, Netflix and Google roles. Plan resume and referral work; visa, deadlines and rolling intake still require exact-role employer evidence.'],quick:['KEEP THE APPLICATION MOVING','Startups: your quick-apply queue.','Use your existing resume when it fits. Review eligibility and required answers before applying.'],pipeline:['MAKE THE NEXT MOVE','Your application pipeline.','Keep applications, referrals and follow-ups in one local workspace.'],network:['THE PEOPLE BEHIND THE ROLES','Start with your network.','Find connections at target employers and write a thoughtful first message.'],sources:['DEEPER THAN THE BIG BOARDS','Ten sources, chosen for you.','Specialized discovery, December graduation, cloud engineering and direct employer pages.'],profile:['EXPERIENCE THAT COUNTS','Where your proof is strongest.','A profile built from your export, with transferable experience and gaps made explicit.'],settings:['FREE, LOCAL, IN YOUR CONTROL','Your local workflow.','Laya handles local AI assessment. Your data and job history stay on this computer.']};
meta.services=['YOUR CONNECTED SEARCH','Job services & Gmail.','Manage your master-profile update queue and import job-alert recommendations.'];
function setView(v){captureBoardContext();view=v;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
function render(){if(!state)return;const m=meta[view];$('#page-kicker').textContent=m[0];$('#page-title').textContent=m[1];$('#page-subtitle').textContent=view==='settings'&&state.storage_mode==='browser'?'Private data stays in this browser. Your laptop runs AI reviews.':m[2];const content=$('#content');content.innerHTML=({actions:renderActions,jobs:renderJobs,prepare:renderJobs,quick:renderJobs,discovery:renderJobs,verification:renderJobs,pipeline:renderPipeline,network:renderNetwork,sources:renderSources,profile:renderProfile,services:()=>window.WorkspaceUI.services(state),settings:renderSettings}[view])();bindView()}
function metric(label,value,note){return `<div class="metric"><span class="label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`}
function renderJobs(){const open=state.jobs.filter(j=>!j.closed&&j.screen.eligible&&!['Applied','Interview','Offer','Rejected','Archived'].includes(j.status)&&(view==='jobs'&&!isFang(j)||(view==='discovery'&&!isFang(j))||view==='verification'||(view==='prepare'?isFang(j):!isFang(j)&&queueFor(j)===view))&&(['discovery','prepare','quick'].includes(view)||(view==='verification'?visaEvidence(j).status!=='confirmed':visaEvidence(j).status==='confirmed'))),ranked=open.filter(j=>j.assessment&&!j.assessment_stale&&j.assessment.tier<=2&&isValidatedFit(j));return `${discoverySummary()}${privateNetworkNotice()}<div class="metrics">${metric('Full descriptions to review',open.filter(j=>j.description_complete).length,open.length+' total engineering discovery leads; scope filter narrows the list')}${metric('Strong fit reviews',ranked.length,'Laya Tier 1 or 2; eligibility still matters')}${metric('With a network connection',open.filter(j=>j.contacts_count).length,'Exact employer or labeled family match')}${metric('In progress',state.jobs.filter(j=>['Applied','Interview','Referral requested'].includes(j.status)).length,'Applications and referral requests')}</div><div class="fit-strip"><span class="fit-symbol">↗</span><div><strong>Your search: evidence-backed engineering roles</strong><p>${esc(state.profile.preferences?.workAuthorization||'Use your profile and employer evidence to check eligibility')}</p></div></div><div class="filters"><input id="job-search" type="search" placeholder="Search company, role or stack" aria-label="Search opportunities"><select id="visa-filter" aria-label="Employer visa evidence"><option value="confirmed" ${!['discovery','prepare','quick','verification'].includes(view)?'selected':''}>OPT accepted (posting or board)</option><option value="pending" ${view==='verification'?'selected':''}>Check OPT / unclear or disputed</option><option value="all" ${['discovery','prepare','quick'].includes(view)?'selected':''}>All visa evidence states</option></select><select id="lane-filter" aria-label="Role lane"><option value="all">All target role families</option><option value="cloud">Cloud & infrastructure</option><option value="backend">Backend, internal tools / full-stack SWE</option><option value="data">Data platform</option></select><select id="scope-filter" aria-label="Discovery role scope"><option value="target" ${view==='discovery'||view==='quick'?'selected':''}>Target role families</option><option value="all" ${!['discovery','quick'].includes(view)?'selected':''}>All engineering discovery</option><option value="unknown">Generic titles: need role details</option></select><select id="tier-filter" aria-label="Fit tier"><option value="all">All review stages</option><option value="priority">Validated AI Tier 1 & 2 only</option><option value="research">Research fit reviews</option><option value="unranked">Needs fit review</option></select><select id="review-filter" aria-label="Description completeness"><option value="complete" ${!['prepare','discovery','jobs'].includes(view)?'selected':''}>Full descriptions first</option><option value="all" ${['prepare','discovery','jobs'].includes(view)?'selected':''}>Include discovery leads</option><option value="incomplete">Need a description</option></select><select id="type-filter" aria-label="Job type"><option value="all">Full-time + internship</option><option value="fulltime">Full-time</option><option value="internship">Internship</option></select><select id="source-filter" aria-label="Source"><option value="all">All sources</option>${jobSourceOptions()}</select><label class="toggle"><input type="checkbox" id="show-excluded">Show conflicts & closed</label></div><div class="jobs-layout"><section><div class="section-heading"><h2>${view==='discovery'?'Potential job leads':'Opportunity shortlist'}</h2><span id="result-count"></span></div><p id="verification-queue" class="muted" role="status">Employer browser verification is optional. Use Verify now on a role.</p><div class="job-list" id="job-list"></div></section><aside><div class="mini-panel"><h3>Eligibility comes first</h3><p>An OPT plan is not approved work authorization. Confirm the employer’s policy, graduation window and actual start date.</p><p>Missing visa details stay visible as “Check with employer”. Explicit conflicts appear only when you switch on conflicts.</p></div><div class="mini-panel"><h3>Proof-based fit review</h3><ul><li>Tier 1: comparable direct proof</li><li>Tier 2: strong transferable work</li><li>Tier 3: adjacent, limited proof</li><li>Tier 4: skip or resolve conflicts</li></ul><p>Listing titles and sponsor tags never count as a complete assessment.</p></div><div class="mini-panel"><h3>Your historical export</h3><span class="big-number">${state.history?.applications||0}</span><p>Past application links imported as history context, separate from open opportunities.</p></div></aside></div>`}
function card(j){const assessment=j.assessment&&!j.assessment_stale?j.assessment:null, grounded=isValidatedFit(j),research=currentResearchReview(j);return `<article class="job-card"><div class="job-top"><div class="company-icon">${esc(j.company.slice(0,2).toUpperCase())}</div><div class="job-main"><h3 class="job-title">${esc(j.title)}</h3><div class="job-company">${esc(j.company)} · ${esc(j.location||'Location needs verification')}</div></div><div class="tier ${assessment?'':'unranked'}">${assessment?(grounded?'Tier '+assessment.tier:'Manual review'):'Needs review'}</div></div><div class="job-meta">${pill(j.screen.lane)}${j.screen.role_family==='adjacent'?pill('Adjacent scope: review proof','warn'):j.screen.role_family==='unverified'?pill('Scope unverified','warn'):''}${reportedVisaBadge(j)}${!j.description_complete?pill('Incomplete description','warn'):''}${j.contacts_count?pill(j.contacts_count+' connection'+(j.contacts_count===1?'':'s'),'good'):''}${j.closed?pill('No longer in feed','bad'):''}${j.screen.issues.length?pill('Eligibility conflict','bad'):''}${j.status!=='Discovered'?pill(j.status,'good'):''}${boardInformationBadge(j)}${browserVerificationBadge(j)}</div>${applicationEligibilityCard(j)}${reportedVisaCard(j)}${research?`<p class="job-note research-fit-note"><strong>Research Tier ${esc(research.tier)}</strong> · ${esc(research.rationale)}<br>Research review; visa and start date remain separate checks.</p>`:''}<div class="job-bottom"><span class="job-note">${esc(sourceName(j))}<br>${esc(j.availability||'Verify employer listing')}</span><button class="small-button" data-select="${esc(j.id)}">${j.source_feedback==='interested'?'Selected ✓':'Select role'}</button><button class="small-button" data-outreach="${esc(j.id)}">Select & draft</button><button class="small-button" data-verify-browser="${esc(j.id)}">Verify now</button><button class="small-button" data-job="${esc(j.id)}">Review role ↗</button></div></article>`}
function filterJobs(){recordVisibleSources();if(!['jobs','prepare','quick','discovery','verification'].includes(view))return;const query=$('#job-search').value.toLowerCase(),lane=$('#lane-filter').value,tier=$('#tier-filter').value,conflicts=$('#show-excluded').checked;let rows=state.jobs.filter(j=>{if(['Applied','Interview','Offer','Rejected','Archived'].includes(j.status))return false;if(!conflicts&&browserHardConflict(j))return false;if(['discovery','jobs'].includes(view)&&isFang(j))return false;const scope=$('#scope-filter').value;if(scope==='target'&&j.screen.role_family==='unverified')return false;if(scope==='unknown'&&j.screen.role_family!=='unverified')return false;const visaFilter=$('#visa-filter').value,visa=visaEvidence(j);if(visaFilter==='confirmed'&&visa.status!=='confirmed')return false;if(visaFilter==='pending'&&visa.status==='confirmed')return false;if(view==='prepare'&&!isFang(j))return false;if(view==='quick'&&(isFang(j)||queueFor(j)!=='quick'))return false;if(!conflicts&&j.source_feedback==='not_interested')return false;if(!conflicts&&(j.closed||!j.screen.eligible||j.status==='Archived'))return false;const completeness=$('#review-filter').value;if(completeness==='complete'&&!j.description_complete)return false;if(completeness==='incomplete'&&j.description_complete)return false;if(lane==='cloud'&&!j.screen.lane.includes('Cloud'))return false;if(lane==='backend'&&!/backend|SWE/i.test(j.screen.lane))return false;if(lane==='data'&&!j.screen.lane.includes('Data'))return false;const jobType=$('#type-filter').value,isIntern=/intern|co.op/i.test(j.title+' '+(j.employment_type||''));if(jobType==='internship'&&!isIntern)return false;if(jobType==='fulltime'&&isIntern)return false;if($('#source-filter').value!=='all'&&sourceId(j)!==$('#source-filter').value)return false;const a=j.assessment&&!j.assessment_stale?j.assessment:null;if(tier==='priority'&&(!a||a.tier>2||!isValidatedFit(j)))return false;if(tier==='unranked'&&isValidatedFit(j))return false;if(tier==='research'&&!currentResearchReview(j))return false;return (j.title+' '+j.company+' '+(j.description||'')).toLowerCase().includes(query)});rows.sort(verificationOrder);scheduleVerification(rows);$('#result-count').textContent=rows.length+' roles';jobPage=Math.min(jobPage,Math.max(1,Math.ceil(rows.length/25)));renderJobList(rows.length?rows.slice((jobPage-1)*25,jobPage*25).map(card).join('')+`<div class="pagination"><button id="prev-page" class="small-button" ${jobPage===1?'disabled':''}>Previous</button><span>Page ${jobPage} of ${Math.ceil(rows.length/25)}</span><button id="next-page" class="small-button" ${jobPage*25>=rows.length?'disabled':''}>Next</button></div>`:`<div class="empty"><h3>${state.jobs.length?'No roles match the current filters.':'Your search workspace is ready.'}</h3><p>${state.jobs.length?'Try another role family, source or scope filter. Generic titles remain available under All engineering discovery. Missing visa information is marked Check with employer.':'Refresh public sources to discover jobs, or import a full description. Source-reported discovery is separate from fit and eligibility.'}</p><button class="primary" id="empty-refresh">Refresh specialized sources</button><button class="secondary" id="empty-browse">Browse discovered jobs</button><button class="secondary" id="empty-visa">Review visa verification queue</button></div>`);document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>openJob(b.dataset.job));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectRole(b.dataset.select));document.querySelectorAll('[data-outreach]').forEach(b=>b.onclick=()=>selectAndDraft(b.dataset.outreach));document.querySelectorAll('[data-verify-browser]').forEach(b=>b.onclick=()=>verifyBrowserNow(b.dataset.verifyBrowser));$('#empty-refresh')?.addEventListener('click',refresh);$('#empty-visa')?.addEventListener('click',()=>setView('verification'));$('#empty-browse')?.addEventListener('click',()=>setView('discovery'));$('#prev-page')?.addEventListener('click',()=>{jobPage--;filterJobs()});$('#next-page')?.addEventListener('click',()=>{jobPage++;filterJobs()})}
function renderPipeline(){const groups=[['Saved','Discovered'],['Referral requested'],['Applied'],['Interview'],['Offer'],['Rejected','Archived']];return `<div class="panel"><p class="muted">Changing a status records your progress. It never submits an application or sends a message.</p><div class="pipeline-grid">${groups.map(g=>{const rows=state.jobs.filter(j=>g.includes(j.status)&&j.status!=='Discovered');return `<section class="pipeline-column"><h3>${esc(g[0])} <span class="muted">${rows.length}</span></h3>${rows.map(j=>`<article class="job-card" tabindex="0" role="button" data-job="${esc(j.id)}"><h4 class="job-title">${esc(j.title)}</h4><div class="job-company">${esc(j.company)}</div>${j.follow_up?`<small>Follow up: ${esc(j.follow_up)}</small>`:''}</article>`).join('')||'<p class="muted">No applications here yet.</p>'}</section>`}).join('')}</div></div>`}
function renderNetwork(){const recruiters=state.network.filter(c=>/recruit|talent|people partner|human resources/i.test(c.position));return `${privateNetworkNotice()}<div class="metrics">${metric('LinkedIn connections',state.network.length,'Exported connections, not verified relationships')}${metric('Recruiting contacts',recruiters.length,'Based on exported role titles')}${metric('Your strongest bridge',state.network.filter(c=>/amazon|\baws\b/i.test(c.company)).length,'Amazon / AWS family connections')}${metric('Email lookup allowance','50','Hunter free shared credits per month')}</div><div class="fit-strip"><span class="fit-symbol">↗</span><div><strong>A connection is a starting point, not a promised referral.</strong><p>Verify their current employer. Start with a warm-up if you haven’t worked together.</p></div></div><div class="filters"><input id="network-search" type="search" placeholder="Find a company, connection or recruiter" aria-label="Search connections"><label class="toggle"><input id="recruiters-only" type="checkbox">Recruiting contacts only</label></div><div class="two-columns"><section class="panel"><div class="section-heading"><h2>Your network</h2><button id="add-contact" class="small-button">＋ Contact record</button></div>${networkRestoreControl()}${renderContactRecords()}<div class="table-wrap"><table><thead><tr><th>PERSON</th><th>EMPLOYER / ROLE</th><th>CONTACT</th></tr></thead><tbody id="network-rows"></tbody></table></div></section><aside class="panel"><h2>Find the right recruiter email</h2><p>Use a recruiting name and the employer’s domain in Hunter’s Email Finder. Finding an email includes verification under its current free plan.</p>${link('https://hunter.io/email-finder','Open Hunter Email Finder ↗','primary')}<p class="muted">50 shared credits monthly; availability is not guaranteed. Keep the lookup source and verification status with the contact.</p>${link('https://help.hunter.io/en/articles/11060999-what-s-included-in-hunter-s-free-plan','Verify free-plan limits')}<div class="detail-section"><h3>Referral workflow</h3><p class="muted">Open a job → inspect employer connections → draft a warm-up or referral request → review and send yourself.</p></div><div class="detail-section"><h3>Published recruiting inboxes</h3>${state.sources.filter(s=>s.contact).map(s=>`<p>${esc(s.name)}<br>${link(s.contact.source_url,s.contact.email)}</p>`).join('')||'<p class="muted">Use the employer career page for verified recruiting contacts.</p>'}</div></aside></div>`}
function filterNetwork(){const q=$('#network-search').value.toLowerCase(),only=$('#recruiters-only').checked;const rows=state.network.filter(c=>(c.name+' '+c.company+' '+c.position).toLowerCase().includes(q)&&(!only||/recruit|talent|people partner|human resources/i.test(c.position)));$('#network-rows').innerHTML=rows.slice(0,100).map(c=>`<tr><td>${link(c.url,c.name||'Unnamed connection')}<small>${esc(c.connected)}</small></td><td>${esc(c.company)}<small>${esc(c.position)}</small></td><td>${c.email?esc(c.email):'<span class="muted">No exported email</span>'}</td></tr>`).join('')||'<tr><td colspan="3">No matching connections.</td></tr>'}
function renderSources(){const rows=[...state.sources].sort((a,b)=>a.priority-b.priority);return `<div class="fit-strip"><span class="fit-symbol">⊙</span><div><strong>Free discovery, with access limits made visible</strong><p>Public API and GitHub feeds refresh here. Other sources open their own search pages for review and import; they aren’t silently scraped.</p></div></div><div class="source-grid">${rows.map((s,i)=>{const result=state.health.refresh?.results?.find(r=>r.source===s.name);return `<article class="source-card"><div class="eyebrow">${String(i+1).padStart(2,'0')} · ${esc(s.access)}</div><h3>${esc(s.name)}</h3><p>${esc(s.why)}</p>${pill(s.free,'good')}${pill(s.feed?'Refreshable feed':'Browse & import')}<p class="limits">${esc(s.limits)}</p><div class="button-row">${link(s.search_url||s.url,'Explore source ↗','secondary')}${link(s.url,'Research source')}</div><div class="source-status">${sourceStats(s)}<br>${result?result.ok?`Last refresh: ${result.retained} target-lane records · ${result.new} new`:'Feed error: '+esc(result.error):'No completed local refresh yet'}</div></article>`}).join('')}</div><div class="panel detail-section"><h2>Eligibility research, alongside discovery</h2>${(state.research.supplemental||[]).map(s=>`<p>${link(s.url,s.name)} — ${esc(s.why)}<br><span class="muted">${esc(s.limits)}</span></p>`).join('')}<h3>Listings excluded during research</h3>${(state.research.rejected||[]).map(s=>`<p>${link(s.url,s.name)}<br><span class="muted">${esc(s.reason)}</span></p>`).join('')}</div>`}
function renderProfile(){const p=state.profile;return window.WorkspaceUI.profile(state)+`<div class="panel"><h2>${esc(p.name)} · your evidence map</h2><p>${esc(p.summary)}</p><div class="job-meta">${pill((state.profile.education?.degree||'Candidate profile')+' · '+(state.profile.education?.graduation||'Confirm graduation'),'good')}${pill(state.profile.preferences?.visa||'Verify authorization','warn')}${pill('US relocation: anywhere')}${pill('Full-time + internships')}</div><div class="two-columns">${(p.roleLanes||[]).map(r=>`<section class="role-card"><span class="eyebrow">${r.priority===1?'PRIMARY SEARCH':'SECONDARY LANE'}</span><h3>${esc(r.name)}</h3><p class="muted">${esc(r.titles.join(' · '))}</p><strong class="muted">Proof you already have</strong><ul>${r.proof.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><strong class="muted">Check the role’s expectations</strong><ul>${r.gaps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`).join('')}</div></div><div class="two-columns detail-section"><section class="panel"><h2>Evidence from your export</h2>${(p.evidence||[]).map(e=>`<div class="evidence">${esc(e.claim)}<small>${esc(e.context||e.type)} · ${esc(e.source)}</small>${e.caution?`<small>${esc(e.caution)}</small>`:''}</div>`).join('')}</section><section class="panel"><h2>Keep the claims accurate</h2><h3>Earned credentials</h3><ul>${(p.earnedCredentials||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Training only</h3><ul>${(p.trainingOnly||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Exclude by default</h3><ul>${(p.excludeByDefault||[]).map(x=>`<li class="muted">${esc(x)}</li>`).join('')}</ul></section></div>`}
function renderSettings(){const l=state.health.laya,ready=l.ready||l.model_ready,validated=l.inference_validated;return `<div class="two-columns"><section class="panel"><h2>Laya · free local assessment</h2><div class="status-line">${pill(ready?'Local model runtime ready':'Setup / model service pending',ready?'good':'warn')}${pill(l.model||'Local model')}${pill(validated===true?'Fit evaluation passed':validated===false?'Fit accuracy not yet validated':'Fit validation status unknown',validated===true?'good':'warn')}</div><p class="muted">${validated===true?'A recorded fit evaluation passed. Review each role’s supporting proof, gaps and eligibility before using its tier.':validated===false?'Service readiness confirms the model can run. Fit accuracy has not passed validation; manually review every supporting claim, gap and eligibility detail.':'Service readiness confirms the model can run. Fit validation status is unavailable; manually review every supporting claim, gap and eligibility detail.'}</p><p>Laya’s actual model pipeline evaluates the full employer description against your evidence. It returns a tier, supporting proof, gaps and eligibility notes.</p><p class="muted">Your model and data run locally. This installation uses a job-fit adapter; it does not connect your email or submit applications.</p><button id="check-health" class="secondary">Check local services</button><div class="detail-section"><h3>Use Simplify with this dashboard</h3><ol><li>Create your free Simplify profile with your current resume, education, experience and links.</li><li>Install Simplify Copilot in regular Chrome, Edge or Firefox and sign in.</li><li>Open the employer listing link in that browser. The extension runs there.</li><li>Let Copilot fill supported fields. Choose your existing or tailored resume for this role.</li><li>Review every answer, especially authorization and future sponsorship, then submit yourself.</li></ol>${link('https://help.simplify.jobs/en/articles/1749022-installing-and-setting-up-copilot','Simplify setup guide')}<h3>Existing outreach tools</h3><p>RoleMule has an existing outreach agent with local Ollama support. Its full app requires additional services and has not been installed here. NetworkAI offers a limited free message allowance. These links do not upload your private profile.</p>${link('https://github.com/eliornl/rolemule','RoleMule source')}${link('https://www.wonsulting.com/networkai','NetworkAI')}${link('https://www.wonsulting.com/pricing','Check free allowance')}<h3>Dedicated messaging workflow</h3><p>Select & draft asks for the message type and tone each time. Local AI chooses verified proof; specialist playbooks generate an email, LinkedIn note and follow-ups. Approve or edit wording to build your private examples.</p><button id="export-message-examples" class="secondary">Export messaging examples</button><p class="muted">The model is specialized through instructions and examples, not fine-tuned weights. Examples are exported for evaluation and future training.</p><h3>Faster application forms</h3><p>Browser Use supports a local browser and Ollama models. It can assist with form filling, but this dashboard’s Laya adapter currently handles fit reviews only.</p>${link('https://github.com/browser-use/browser-use/blob/main/examples/models/ollama.py','Browser Use + Ollama example')}<p>Simplify Copilot offers free autofill on supported employer forms. It uses a Simplify account and is a separate service.</p>${link('https://simplify.jobs/copilot','Simplify Copilot')}<p class="muted">Review every answer. Keep authorization, sponsorship, demographic answers and final submission under your control. No application autofill agent is installed by this dashboard.</p></div><div class="detail-section"><h3>Source refresh</h3><p class="muted">Refresh runs on demand while the dashboard server is open. The last successful source check is stored locally. A failed feed never marks jobs closed.</p>${state.health.refresh?.results?.map(r=>`<p class="muted">${esc(r.source)}: ${r.ok?r.retained+' retained, '+r.new+' new':'error — '+esc(r.error)}</p>`).join('')||'<p class="muted">No refresh completed yet.</p>'}</div></section><section class="panel"><h2>Your data controls</h2><p>${state.storage_mode==='browser'?'Your profile, connections, notes and drafts stay in this browser’s private storage. Clearing site data removes them; export a backup regularly.':'Your LinkedIn export remains in the original folder. Job status, notes, drafts and fit reviews are saved in a local SQLite database.'}</p><button id="export-backup" class="primary">Export workspace backup</button><p class="muted">The backup contains your profile, network, job records and drafts. Store it privately.</p><div class="detail-section"><h3>Restore LinkedIn connections only</h3>${networkRestoreControl()}<h3>Private backup & local AI pairing</h3>${state.storage_mode==='browser'?`<label>Import your local workspace backup<input id="import-backup-file" type="file" accept="application/json,.json"></label><label>Local pairing key<input id="pairing-key" type="password" autocomplete="off" placeholder="Copy from the local dashboard on your laptop"></label><button id="pair-local" class="secondary">Pair local AI for this tab</button><p class="muted">The key stays in this tab’s session storage. Your browser may ask for local-network access. Your laptop must run the local launcher.</p>`:`<button id="open-hosted" class="primary">Open my hosted workspace with private data</button><button id="copy-pairing" class="secondary">Copy local AI pairing key</button><p class="muted">Paste this key only into your own hosted workspace. It authorizes model review and expires when the local server restarts.</p>`}</div><div class="detail-section"><h3>Still worth clarifying</h3><p class="muted">Minimum salary, exact authorized start date and remote/onsite preference. No salary cutoff is applied until you choose one.</p><label>Minimum annual salary (USD; optional)<input id="salary-min" type="number" min="0" step="1000" value="${esc(state.preferences.salary_min||'')}" placeholder="No cutoff"></label><button id="save-preferences" class="secondary">Save preference</button><p class="muted">Salary preference is recorded for review; unknown salary and internship hourly pay won’t be silently rejected.</p></div>${link('https://github.com/aayushch/laya','Laya source and documentation ↗')}</section></div>`}
function bindView(){window.WorkspaceUI.bind(state,{api,load,message,setView});if(view==='actions'){bindActions();scheduleVerification([])}bindImportNotices();bindDiscoveryLinks();setTimeout(bindHostedControls,0);if(view==='network')setTimeout(bindContacts,0);if(['jobs','prepare','quick','discovery','verification'].includes(view)){restoreBoardContext();['job-search','lane-filter','scope-filter','tier-filter','review-filter','type-filter','source-filter','visa-filter','show-excluded'].forEach(id=>$('#'+id).addEventListener('input',()=>{jobPage=1;filterJobs()}));filterJobs()}if(view==='network'){['network-search','recruiters-only'].forEach(id=>$('#'+id).addEventListener('input',filterNetwork));filterNetwork()}document.querySelectorAll('[data-job]').forEach(b=>{b.onclick=()=>openJob(b.dataset.job);b.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();openJob(b.dataset.job)}}});$('#check-health')?.addEventListener('click',async()=>{try{state.health=await api('/api/health');render();message('Local service status updated.')}catch(e){message(e.message,true)}});$('#export-backup')?.addEventListener('click',async()=>{const d=await api('/api/backup');const url=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='private-career-workspace-backup.json';a.click();URL.revokeObjectURL(url)});$('#save-preferences')?.addEventListener('click',async()=>{try{state.preferences=await api('/api/preferences',{salary_min:$('#salary-min').value?Number($('#salary-min').value):null});message('Salary preference saved for job review.')}catch(e){message(e.message,true)}})}
async function openJob(id){if($('#detail').open)rememberDetailDraft();activeJob=state.jobs.find(j=>j.id===id);if(!activeJob){message('Job record unavailable. Import a valid backup.',true);return}const contacts=await api('/api/contacts/'+encodeURIComponent(activeJob.company));api('/api/source-events',{job_id:id,kind:'shown'}).catch(()=>{});renderDetail(contacts);if(!$('#detail').open)$('#detail').showModal()}
function renderDetail(contacts){const j=activeJob,a=j.assessment&&!j.assessment_stale?j.assessment:null,fitValidated=isValidatedFit(j);$('#detail-body').innerHTML=`<h2>${esc(j.title)}</h2><p class="muted">${esc(j.company)} · ${esc(j.location)}</p><div id="detail-draft-notice" class="draft-notice" role="status" hidden><strong>Unsaved edits kept for this role.</strong> Save the relevant section. These edits remain while this page is open; refreshing the page clears them. <button id="discard-detail-draft" class="small-button">Discard unsaved edits</button></div><nav class="role-section-nav" aria-label="Role sections"><button class="small-button" data-role-section="browser-verification-panel">Eligibility & evidence</button><button class="small-button" data-role-section="application-plan">Application plan</button><button class="small-button" data-role-section="progress-notes">Progress & notes</button></nav><div class="job-meta">${pill(j.screen.lane)}${j.screen.role_family==='adjacent'?pill('Adjacent scope: review proof','warn'):j.screen.role_family==='unverified'?pill('Scope unverified','warn'):''}${reportedVisaBadge(j)}${!j.description_complete?pill('Incomplete description','warn'):''}${pill(j.screen.location_status)}</div><p>${link(j.url,j.employer_verification?.posting_live===true?'Open employer application ↗':'Open listing / company page ↗','primary')}</p><div class="two-columns"><label>Application stage<select id="job-status">${statusOptions(j.status)}</select></label><label>Follow-up date<input id="follow-up" type="date" value="${esc(j.follow_up||'')}"></label></div>${browserVerificationPanel(j)}${reportedVisaPanel(j)}${boardInformationPanel(j)}${workflowPanel(j)}${employerPanel(j)}${researchReviewPanel(j)}<button id="verify-browser-detail" class="primary">Verify this job now</button><button id="verify-employer" class="secondary">Optional: check employer posting via API</button><p class="muted">Use the reported listing details and flag incorrect information above. Missing OPT, future sponsorship or start information is for you to check. Saved employer evidence remains available below.</p>${j.screen.review_notes?.length?`<section class="detail-section"><h3>Scope to review</h3><ul>${j.screen.review_notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul><p class="muted">These notes classify discovery scope, not candidate fit or employer visa approval.</p></section>`:''}${j.screen.issues.length?`<div class="detail-section"><h3>Eligibility conflicts to resolve</h3><ul>${j.screen.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<div class="detail-section"><div class="section-heading"><h3>Fit review ${a?(fitValidated?'· Tier '+a.tier:'· Needs manual review'):''}</h3><button id="rank-job" class="small-button">Review with local Laya</button></div>${a?`${fitValidated?'':'<p class="muted">Unvalidated model suggestion: Tier '+esc(a.tier)+'. Manually review every supporting claim, gap and eligibility detail.</p>'}<p>${fitValidated?'':'Model suggestion: '}${esc(a.verdict)}</p>${pill('Confidence: '+a.confidence)}${pill('Assessed by Laya · '+(a.model||'local model'))}${(a.evidence||[]).map(e=>`<div class="assessment-evidence"><strong>${esc(typeof e==='string'?'Supporting proof':e.requirement)}</strong><span>${esc(typeof e==='string'?e:e.proof)}</span>${typeof e==='object'?`<small>Candidate sources: ${esc((e.source_ids||[]).join(', '))}</small>`:''}</div>`).join('')}<h3>Gaps & checks</h3>${(a.specificity_warnings||a.warnings)?.length?`<p class="muted">${esc((a.specificity_warnings||a.warnings).join(' · '))}</p>`:''}<ul>${(a.gaps||[]).map(g=>`<li class="muted">${esc(typeof g==='string'?g:JSON.stringify(g))}</li>`).join('')}</ul><p class="muted">${esc(a.sponsorship?.note||'')} ${esc(a.start_date?.note||'')}</p>`:`<p class="muted">${j.assessment_stale?'The description changed. Run a new review.':'No AI fit verdict yet. Laya needs the full job description, your proof and eligibility context.'}</p>`}</div><div class="detail-section"><h3>People at this employer</h3>${contacts.length?contacts.map((c,i)=>`<div class="contact"><strong>${esc(c.name||'Unnamed connection')}</strong> ${pill(c.match_type||'Employer match')}<small>${esc(c.company)} · ${esc(c.position)}</small><div class="button-row">${link(c.url,'Check profile ↗','small-button')}<button class="small-button contact-draft" data-index="${i}" data-kind="warmup">Draft a warm-up</button><button class="small-button contact-draft" data-index="${i}" data-kind="referral">Draft referral request</button></div></div>`).join(''):privateNetworkNotice()+'<p class="muted">No employer matches in the imported network for this role. A matching connection is a potential contact, not a promised referral.</p>'}<div class="two-columns"><label>Recruiter name<input id="recruiter-name" placeholder="Name from employer page or LinkedIn"></label><label>Recruiter email (optional)<input id="recruiter-email" type="email" placeholder="Verified email only"></label></div><div class="button-row"><button id="recruiter-draft" class="secondary">Draft recruiter outreach</button>${link('https://hunter.io/email-finder','Find & verify email ↗','small-button')}</div></div><div class="detail-section"><h3>Full employer description</h3><p class="muted">${j.description_complete===false?'Research summary only — paste the full description before ranking.':'Review the original posting for current requirements.'}</p><textarea id="job-description" rows="9" class="note-area">${esc(j.description||'')}</textarea><button id="save-description" class="small-button">Save description</button></div><div class="detail-section"><h3>Help improve future fit reviews</h3><div class="two-columns"><label>Your assessment<select id="feedback-label"><option value="good_fit">Good fit</option><option value="not_fit">Not a fit</option><option value="unsure">Unsure</option></select></label><label>Corrected tier (optional)<select id="corrected-tier"><option value="">No correction</option><option>1</option><option>2</option><option>3</option><option>4</option></select></label></div><label>Reason<textarea id="feedback-reason" rows="2" placeholder="Which evidence, requirement or eligibility detail matters?"></textarea></label><button id="fit-feedback" class="secondary">Save feedback</button><p class="muted">Feedback builds an evaluation dataset. It does not automatically retrain the model.</p></div><div id="progress-notes" class="detail-section"><h3>Your notes</h3><textarea id="job-notes" rows="3" class="note-area" placeholder="Resume version, eligibility reply, interview notes…">${esc(j.notes||'')}</textarea><button id="save-job" class="secondary">Save progress & notes</button></div>`;
restoreDetailDraft(j);document.querySelectorAll('[data-role-section]').forEach(b=>b.onclick=()=>{$('#'+b.dataset.roleSection)?.scrollIntoView({block:'start'})});bindWorkflow(j);bindBoardInformationFeedback(j);bindImportNotices();$('#eligibility-draft')?.addEventListener('click',()=>makeDraft(j.id,'eligibility',{name:$('#recruiter-name')?.value||'',email:$('#recruiter-email')?.value||'',company:j.company}));$('#verify-employer').onclick=async()=>{const b=$('#verify-employer');b.disabled=true;b.textContent='Checking employer…';try{await api('/api/jobs/'+j.id+'/verify',{});await load();await openJob(j.id);message('Employer ATS checked. Missing deadline or visa policy stays unknown.')}catch(e){message(e.message,true);b.disabled=false;b.textContent='Check current employer ATS'}};
$('#fit-feedback').onclick=async()=>{try{await api('/api/feedback',{job_id:j.id,label:$('#feedback-label').value,reason:$('#feedback-reason').value,corrected_tier:$('#corrected-tier').value?Number($('#corrected-tier').value):null});message('Feedback saved for evaluation and calibration.')}catch(e){message(e.message,true)}};
$('#verify-browser-detail').onclick=()=>verifyBrowserNow(j.id);
$('#save-job').onclick=async()=>{try{await saveDetailUpdate(j,{status:$('#job-status').value,follow_up:$('#follow-up').value,notes:$('#job-notes').value},['job-status','follow-up','job-notes']);message('Progress saved locally.')}catch(e){message(e.message,true)}};
$('#save-description').onclick=async()=>{try{await saveDetailUpdate(j,{description:$('#job-description').value},['job-description']);message('Description saved; the next fit review will use this text.')}catch(e){message(e.message,true)}};
$('#rank-job').onclick=async()=>{const b=$('#rank-job');b.disabled=true;b.textContent='Laya is reviewing…';try{await api('/api/jobs/'+j.id+'/rank',{});await load();await openJob(j.id);message('Laya fit review saved. Check the supporting proof and eligibility notes.')}catch(e){message(e.message,true);b.disabled=false;b.textContent='Review with local Laya'}};
document.querySelectorAll('.contact-draft').forEach(b=>b.onclick=()=>makeDraft(j.id,b.dataset.kind,contacts[Number(b.dataset.index)]));$('#recruiter-draft').onclick=()=>makeDraft(j.id,'recruiter',{name:$('#recruiter-name').value,email:$('#recruiter-email').value,company:j.company})}
let pendingDraft,activeDraftChannel;
async function makeDraft(id,kind,contact){pendingDraft={id,kind,contact};$('#draft-setup-form').reset();$('#setup-voice').value='';$('#setup-channel').value='';$('#setup-kind').value=kind||'';$('#setup-recipient').value=contact?.name||'';$('#setup-relationship').value=contact?.relationship||(contact?.connected?'LinkedIn connection':'Unknown');$('#draft-setup').showModal()}
$('#close-draft-setup').onclick=()=>$('#draft-setup').close();
$('#draft-setup-form').onsubmit=async event=>{event.preventDefault();const button=$('#generate-outreach');button.disabled=true;button.textContent='Preparing your draft…';try{const contact={...pendingDraft.contact,name:$('#setup-recipient').value,relationship:$('#setup-relationship').value};draftData=await api('/api/jobs/'+pendingDraft.id+'/draft',{kind:$('#setup-kind').value,contact,voice:$('#setup-voice').value});$('#draft-setup').close();$('#draft-title').textContent='Your outreach draft';$('#draft-meta').textContent='For '+(contact.name||'a recipient to confirm')+' · '+draftData.voice+' · Not sent';$('#draft-method').textContent=draftData.technique+' · '+draftData.method+'. '+(draftData.warnings||[]).join(' ');$('#draft-channel').innerHTML=Object.entries(draftData.messages||{email:{label:'Email',subject:draftData.subject,body:draftData.body}}).map(([key,m])=>`<option value="${key}">${esc(m.label)}</option>`).join('');activeDraftChannel=$('#setup-channel').value;$('#draft-channel').value=activeDraftChannel;showDraftChannel(activeDraftChannel);$('#message-feedback-reason').value='';$('#approve-draft').textContent='Approve wording for learning';$('#draft-dialog').showModal()}catch(e){message(e.message,true)}finally{button.disabled=false;button.textContent='Generate draft'}};
function showDraftChannel(channel){const m=draftData.edits?.[channel]||draftData.messages?.[channel]||draftData;$('#draft-subject').value=m.subject||'';$('#draft-body').value=m.body||'';updateMailDraft()}
$('#draft-channel').onchange=()=>{draftData.edits??={};draftData.edits[activeDraftChannel]={subject:$('#draft-subject').value,body:$('#draft-body').value};activeDraftChannel=$('#draft-channel').value;showDraftChannel(activeDraftChannel)};
async function messageFeedback(label){try{const original=draftData.messages[activeDraftChannel];const edited=$('#draft-body').value!==original.body||$('#draft-subject').value!==original.subject;await api('/api/drafts/'+draftData.id+'/feedback',{label:label==='approved'&&edited?'edited':label,channel:activeDraftChannel,subject:$('#draft-subject').value,body:$('#draft-body').value,reason:$('#message-feedback-reason').value});message('Messaging example saved privately. No message was sent and model weights were not changed.');if(label==='approved')$('#approve-draft').textContent='Wording approved ✓'}catch(e){message(e.message,true)}}
$('#approve-draft').onclick=()=>messageFeedback('approved');$('#reject-draft').onclick=()=>messageFeedback('rejected');
async function selectAndDraft(id){try{const j=state.jobs.find(x=>x.id===id);await api('/api/jobs/'+id+'/update',{source_feedback:'interested',...(j.status==='Discovered'?{status:'Saved'}:{})});const people=await api('/api/contacts/'+encodeURIComponent(j.company));const contact=people.find(c=>c.match_type==='Exact employer match')||{};await load();await makeDraft(id,'',contact)}catch(e){message(e.message,true)}}
function updateMailDraft(){const email=draftData?.contact?.email||'';$('#email-draft').hidden=!email||activeDraftChannel!=='email';$('#email-draft').href='mailto:'+encodeURIComponent(email)+'?subject='+encodeURIComponent($('#draft-subject').value)+'&body='+encodeURIComponent($('#draft-body').value)}
async function refresh(){try{await api('/api/refresh',{});$('#refresh').disabled=true;$('#refresh').textContent='Refreshing…';message('Checking verified public feeds. Manual sources remain browse-and-import.');clearTimeout(pollTimer);pollRefresh()}catch(e){message(e.message,true)}}
async function pollRefresh(){try{const r=await api('/api/refresh');if(r.running){message('Refreshing specialized sources · '+r.results.length+' feeds checked');pollTimer=setTimeout(pollRefresh,3000)}else{$('#refresh').disabled=false;$('#refresh').textContent='↻ Refresh jobs';await load();message(r.error||'Refresh complete: '+r.results.filter(x=>x.ok).length+' feeds checked, '+r.results.reduce((n,x)=>n+(x.new||0),0)+' new target-lane records. '+r.results.filter(x=>!x.ok).length+' feed errors.',!!r.error)}}catch(e){message(e.message,true);$('#refresh').disabled=false}}
document.querySelectorAll('nav [data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#refresh').onclick=refresh;$('#add-job').onclick=()=>$('#import-dialog').showModal();$('#close-detail').onclick=()=>{rememberDetailDraft();$('#detail').close()};$('#detail').addEventListener('cancel',()=>rememberDetailDraft());$('#close-import').onclick=()=>$('#import-dialog').close();$('#close-draft').onclick=()=>$('#draft-dialog').close();$('#draft-subject').oninput=updateMailDraft;$('#draft-body').oninput=updateMailDraft;$('#copy-draft').onclick=async()=>{try{await navigator.clipboard.writeText('Subject: '+$('#draft-subject').value+'\n\n'+$('#draft-body').value);$('#copy-draft').textContent='Copied';setTimeout(()=>$('#copy-draft').textContent='Copy draft',1800)}catch{message('Select and copy the draft text manually.',true)}};$('#import-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));await api('/api/jobs',data);$('#import-dialog').close();e.target.reset();await load();message('Opportunity imported. Check its eligibility and request a fit review.')}catch(err){message(err.message,true)}};
load().catch(e=>{$('#loading').textContent='Could not read the workspace: '+e.message});
function renderContactRecords(){return `<div class="detail-section"><h3>Saved recruiter & referral contacts</h3>${(state.contacts||[]).map(c=>`<div class="contact"><strong>${esc(c.name||'Unnamed connection')}</strong> ${pill(c.verification,c.verification==='Unverified'?'warn':'good')}<small>${esc(c.company)} · ${esc(c.relationship)} · ${esc(c.email||'No email saved')}</small><div class="button-row"><button class="small-button edit-contact" data-contact-id="${esc(c.id)}">Edit record</button>${c.source_url?link(c.source_url,'Check source ↗','small-button'):''}</div></div>`).join('')||'<p class="muted">Save relevant contacts with their email source, relationship and verification status.</p>'}</div>`}
function bindContacts(){document.querySelectorAll('.edit-contact').forEach(b=>b.onclick=()=>openContact(state.contacts.find(c=>c.id===b.dataset.contactId)));$('#add-contact')?.addEventListener('click',()=>openContact())}
function openContact(contact){const form=$('#contact-form');form.reset();form.elements.id.value='';$('#contact-error').textContent='';if(contact){for(const [key,value]of Object.entries(contact)){if(form.elements[key])form.elements[key].value=key==='verified_at'?String(value||'').slice(0,10):value||''}}$('#contact-dialog').showModal()}
$('#close-contact').onclick=()=>$('#contact-dialog').close();
$('#contact-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const payload=Object.fromEntries(new FormData(form));const id=payload.id;delete payload.id;if(payload.verified_at)payload.verified_at=new Date(payload.verified_at+'T12:00:00Z').toISOString();try{await api(id?'/api/contacts/'+id+'/update':'/api/contacts',payload);$('#contact-dialog').close();await load();message('Contact saved locally with source and verification notes.')}catch(err){$('#contact-error').textContent=err.message}};

function bindHostedControls(){
$('#restore-network-file')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40000000)throw Error('The backup file exceeds 40 MB');const value=JSON.parse(await file.text());const result=await api('/api/import-network',value);await load();message(result.connections+' LinkedIn connections restored privately. Your existing job progress, notes and drafts were preserved.')}catch(error){message(error.message,true)}});
$('#export-message-examples')?.addEventListener('click',async()=>{try{const examples=await api('/api/message-training');const blob=new Blob([JSON.stringify(examples,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='private-messaging-examples.json';a.click();URL.revokeObjectURL(url)}catch(e){message(e.message,true)}});
$('#open-hosted')?.addEventListener('click',openHostedPrivate);
$('#copy-pairing')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(state.token);message('Local AI pairing key copied.')}catch{message('Clipboard unavailable. Use a browser that allows copying.',true)}});
$('#pair-local')?.addEventListener('click',async()=>{try{window.careerPairLocal($('#pairing-key').value);state.health=await api('/api/health');render();message(state.health.laya.ready?'Local AI runtime paired and ready. Check fit-validation status and review supporting proof.':'Local service not ready; check the launcher and allowed hosted origin.')}catch(e){message(e.message,true)}});
$('#import-backup-file')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const value=JSON.parse(await file.text());await api('/api/import-backup',value);await load();message('Private workspace imported into this browser.')}catch(e){message(e.message,true)}});
}

function employerPanel(j){
const v=j.employer_verification;const eligibility=visaEvidence(j);const eligibilityButton='<button id="eligibility-draft" class="secondary">Draft employer eligibility questions</button>';
if(!v)return `<section class="detail-section employer-check">${employerOriginChain(j,{})}<h3>Optional employer check</h3><p>Board or posting OPT wording is used for the shortlist. Use Verify now if you want a deeper check on the company’s careers site.</p><p>Deadline, F-1/OPT acceptance, future sponsorship and start date: <strong>not verified</strong>.</p>${eligibilityButton}</section>`;
const d=v.deadline||{},visa=v.visa||{},timing=v.timing||{};
const age=(Date.now()-Date.parse(v.checked_at))/86400000;
return `<section class="detail-section employer-check"><h3>Original employer check</h3>${employerOriginChain(j,v)}<p>${pill(eligibility.label,eligibility.status==='confirmed'?'good':'warn')}</p><p class="muted">${esc(eligibility.reason)} Employer policy evidence does not approve your OPT or guarantee a visa. Your authorization and start date still need confirmation.</p>${eligibilityButton}<p>${pill(v.posting_live===true?'Listed when checked':v.posting_live===false?'Employer reports closed':'Availability unconfirmed',v.posting_live===true?'good':'warn')}${age>7?pill('Recheck: evidence is over 7 days old','warn'):''}</p><div class="two-columns"><div><strong>Application deadline</strong><p>${esc(d.value||d.status||'Not published')}</p>${d.evidence_quote?`<p class="muted">Employer wording: ${esc(d.evidence_quote)} ${link(d.source_url,'Deadline source','small-button')}</p>`:''}<strong>F-1 / OPT acceptance</strong><p>${esc(visa.f1_opt||'unknown')}</p></div><div><strong>Future H-1B sponsorship (optional)</strong><p>${esc(visa.future_sponsorship||'unknown')}</p><strong>Start date / graduation window</strong><p>${esc(timing.start_date||timing.status||'Needs confirmation')}</p></div></div>${visa.evidence_quote?`<div class="detail-section visa-policy-quote"><strong>Exact posting policy evidence</strong><p>${esc(visa.evidence_quote)}</p>${link(visa.source_url,'Open exact policy source','small-button')}</div>`:''}<p class="muted">${esc(visa.notes||'Confirm any missing initial OPT details. Future H-1B is optional for this search.')} ${esc(timing.notes||'')}</p><p class="muted">Checked ${esc(String(v.checked_at||'').slice(0,10))}. “Not published” does not mean no deadline. Recheck before applying.</p></section>`;
}

function sourceId(j){return j.discovered_source_id||j.source_id||'manual'}
function sourceName(j){return state.sources.find(s=>s.id===sourceId(j))?.name||j.discovered_source||j.source||'Imported job'}
function sourceStats(s){const jobs=state.jobs.filter(j=>sourceId(j)===s.id),yes=jobs.filter(j=>j.source_feedback==='interested').length,no=jobs.filter(j=>j.source_feedback==='not_interested').length,correct=jobs.filter(j=>j.information_feedback?.verdict==='correct').length,incorrect=jobs.filter(j=>j.information_feedback?.verdict==='incorrect').length,unsure=jobs.filter(j=>j.information_feedback?.verdict==='unsure').length;return `${yes} selected · ${no} not interested · ${jobs.length} discovered.<br>${correct} user-reported correct · ${incorrect} user-reported incorrect · ${unsure} unsure. User feedback; not verified employer policy or an AI fit score.`}
function queueFor(j){if(j.application_queue)return j.application_queue;const company=j.company.toLowerCase();if(isFang(j))return 'prepare';if(/^(rinse|namespace|baseten|eventual)(\b|\s|\/)/.test(company)||sourceId(j)==='yc')return 'quick';return 'discovery'}
async function selectRole(id){const j=state.jobs.find(x=>x.id===id);try{await api('/api/jobs/'+id+'/update',{source_feedback:j.source_feedback==='interested'?'cleared':'interested',...(j.status==='Discovered'?{status:'Saved'}:{})});await load();message('Selection saved as feedback for '+sourceName(j)+'.')}catch(e){message(e.message,true)}}
function workflowPanel(j){const ids=[...new Set([sourceId(j),...Object.keys(j.source_sightings||{})])];const sourceLinks=ids.map(id=>{const s=state.sources.find(x=>x.id===id);return s?link(s.search_url||s.url,s.name):esc(id)}).join(' · ');const q=queueFor(j);return `<section id="application-plan" class="detail-section"><h3>Discovery source & application plan</h3><p>Recorded discovery source: <strong>${esc(sourceName(j))}</strong></p><p class="muted">Also seen in: ${sourceLinks}. Employer verification is a separate check.</p><div class="two-columns"><label>Feedback for this job board<select id="source-feedback"><option value="cleared" ${!j.source_feedback||j.source_feedback==='cleared'?'selected':''}>No preference yet</option><option value="interested" ${j.source_feedback==='interested'?'selected':''}>Selected / interested</option><option value="not_interested" ${j.source_feedback==='not_interested'?'selected':''}>Not interested</option></select></label><label>Application queue<select id="application-queue"><option value="prepare" ${q==='prepare'?'selected':''}>Preparation workflow</option><option value="quick" ${q==='quick'?'selected':''}>Startup / quick apply</option><option value="discovery" ${q==='discovery'?'selected':''}>General discovery</option></select></label></div><label>Resume version / filename<input id="resume-version" value="${esc(j.resume_version||'')}" placeholder="e.g. cloud-resume-v3.pdf (record only)"></label><div class="workflow-checks">${[['resume_ready',q==='quick'?'Existing resume fits this role':'Resume tailored and reviewed'],['referral_ready','Referral outreach reviewed / not needed'],['eligibility_reviewed','Employer visa, deadline and start-date checks reviewed'],['application_checked','Required answers reviewed']].map(([key,label])=>`<label class="toggle"><input type="checkbox" id="plan-${key}" ${j[key]?'checked':''}>${esc(label)}</label>`).join('')}</div><p class="muted">This is your checklist, not verified employer approval. Rolling intake remains unconfirmed unless the employer states it. Quick apply opens the employer form; it does not submit an application.</p><button id="save-plan" class="secondary">Save application plan</button></section>`}
function bindWorkflow(j){$('#save-plan').onclick=async()=>{try{const body={source_feedback:$('#source-feedback').value,application_queue:$('#application-queue').value,resume_version:$('#resume-version').value};for(const key of ['resume_ready','referral_ready','eligibility_reviewed','application_checked'])body[key]=$('#plan-'+key).checked;await saveDetailUpdate(j,body,['source-feedback','application-queue','resume-version','plan-resume_ready','plan-referral_ready','plan-eligibility_reviewed','plan-application_checked']);message('Application plan and source feedback saved.')}catch(e){message(e.message,true)}}}

function openHostedPrivate(){
if(!state.hosted_url){message('Hosted deployment URL is not available yet.',true);return}
const target=new URL(state.hosted_url);let popup;
const listener=async event=>{if(event.origin!==target.origin||event.source!==popup||event.data?.type!=='career-workspace-ready')return;window.removeEventListener('message',listener);try{const backup=await api('/api/backup');popup.postMessage({type:'career-private-import',backup,pairing_key:state.token},target.origin);message('Private data transferred directly between your browser tabs.')}catch(e){message(e.message,true)}};
window.addEventListener('message',listener);popup=window.open(target.href,'career-workspace-hosted');
if(!popup){window.removeEventListener('message',listener);message('Allow the popup, or export a private backup and import it on the hosted site.',true)}
setTimeout(()=>window.removeEventListener('message',listener),30000);
}
window.addEventListener('career-workspace-imported',()=>load().then(()=>message('Private workspace imported from your local tab. Local AI paired for this session.')).catch(e=>message(e.message,true)));

function isValidatedFit(job){return !job.assessment_stale&&job.assessment?.grounding_valid===true&&job.assessment.inference_validated===true&&Number.isInteger(job.assessment.tier)&&job.assessment.tier>=1&&job.assessment.tier<=4}
function currentFitTier(job){return isValidatedFit(job)?job.assessment.tier:9}

function normalizedRoleURL(value){try{const u=new URL(safeLink(value));u.hash='';for(const k of [...u.searchParams.keys()])if(/^utm_|^(ref|referrer|gh_src|source)$/i.test(k))u.searchParams.delete(k);u.searchParams.sort();u.pathname=u.pathname.replace(/\/$/,'');return u.href.replace(/\/$/,'')}catch{return ''}}
function reportedVisa(job){
const feedback=job.information_feedback;
if(feedback?.verdict==='incorrect'&&feedback.field==='visa')return {status:'disputed',label:'OPT information is disputed · check with employer',quotes:[],source_url:job.url,source:sourceName(job)};
const hint=String(job.sponsorship_hint??'').trim(),unknown=/^(?:unknown|not stated|n\/a|none|null|undefined|)$/i.test(hint);
const text=String(job.description||'');
const quotes=text.split(/\n+|(?<=[.!?])\s+/).map(s=>s.trim()).filter(s=>
 /\b(?:OPT|CPT|H[- ]?1B)\b|(?:visa|immigration|employment).{0,35}sponsor|sponsor.{0,35}(?:visa|international)/i.test(s)&&
 !/\?|\b(?:will you|do you|are you|please select|please specify)\b/i.test(s)&&
 !/historically|past (?:h.?1b|sponsorship)|sponsorship history/i.test(s)).slice(0,3).map(s=>{if(s.length<=500)return s;const match=s.search(/\b(?:OPT|CPT|H[- ]?1B)\b|(?:visa|immigration|employment).{0,35}sponsor|sponsor.{0,35}(?:visa|international)/i);return '…'+s.slice(Math.max(0,match-80),match+340)+'…'});
if(!unknown)quotes.unshift('Source sponsorship tag: '+hint);
const source_url=safeLink(job.description_source_url)||safeLink(job.url),posting=!!job.description_source_url;
return {status:quotes.length?'reported':'unknown',label:quotes.length?(posting?'Posting-reported visa details':'Board-reported visa details'):'Check with employer · visa not stated',quotes:[...new Set(quotes)].slice(0,3),source_url,source:posting?'Recorded posting':sourceName(job)};
}
function reportedVisaBadge(job){const info=reportedVisa(job);return pill(info.label,info.status==='disputed'?'bad':'warn')}
function reportedVisaCard(job){const info=reportedVisa(job);return info.quotes.length?`<p class="job-note board-visa-summary">${esc(info.quotes[0].slice(0,220))}${info.quotes[0].length>220?'…':''}</p>`:''}
function reportedVisaPanel(job){const info=reportedVisa(job);return `<section class="detail-section reported-visa"><h3>Visa information from the listing</h3><p>${reportedVisaBadge(job)}</p>${info.quotes.length?info.quotes.map(q=>`<blockquote>${esc(q)}</blockquote>`).join(''):'<p><strong>Check with employer.</strong> Initial OPT acceptance and future sponsorship are not stated in the available listing, or you flagged the information as incorrect.</p>'}<p>${esc(info.source)} · ${link(info.source_url,'Listing information source','small-button')}</p><p class="muted">Reported wording is shown as written. STEM OPT, initial OPT and H-1B transfers are different; a statement about one does not answer the others. Check any missing details yourself and report incorrect information below.</p></section>`}
function originalVisaEvidence(job){
const {browser_verification,...listing}=job;return window.OPTPolicy.evaluate(listing);
}

function isFang(job){const k=String(job.company||'').toLowerCase().replace(/\b(incorporated|corporation|company|limited|inc|corp|ltd|llc)\b/g,'').replace(/[^a-z0-9]/g,'');return ['amazon','amazonwebservices','amazonwebservicesaws','aws','google','googlecloud','alphabet','meta','metaplatforms','facebook','netflix'].includes(k)}

function privateNetworkNotice(){if(state.storage_mode!=='browser'||state.network.length)return '';return `<section class="panel detail-section"><h3>Import your LinkedIn connections</h3><p>This hosted browser has no imported LinkedIn connections yet. Your personal network is kept privately and is not included in the public website.</p><p>Export a private workspace backup from your laptop, then choose “Restore connections only” here. This keeps your current applications, notes and drafts. Full workspace import is available separately in Local workflow.</p><div class="button-row">${link('http://127.0.0.1:8765/','Open local dashboard','secondary')}<button class="primary" data-import-network>Restore connections only</button></div></section>`}
function bindImportNotices(){document.querySelectorAll('[data-import-network]').forEach(b=>b.onclick=()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());setView('settings');$('#restore-network-file')?.scrollIntoView({block:'center'});$('#restore-network-file')?.focus()})}

function networkRestoreControl(){return state.storage_mode==='browser'?`<section class="detail-section"><label>Restore connections only<input id="restore-network-file" type="file" accept="application/json,.json"></label><p class="muted">Choose your private workspace backup. Only LinkedIn connections and employer-family mappings are restored. Existing jobs, statuses, notes, drafts, recruiter contact records and preferences stay as they are.</p></section>`:''}

function discoverySummary(){const active=state.jobs.filter(j=>!j.closed&&!['Applied','Interview','Offer','Rejected','Archived'].includes(j.status)),potential=active.filter(j=>j.screen.eligible),full=active.filter(j=>j.description_complete),pending=potential.filter(j=>visaEvidence(j).status==='pending'),confirmed=potential.filter(j=>visaEvidence(j).status==='confirmed'),validated=potential.filter(j=>isValidatedFit(j));return `<section class="panel detail-section discovery-summary"><h2>Your discovery overview</h2><p class="muted">Show roles whose current posting or job board explicitly accepts initial OPT. Future H-1B is optional. Missing or disputed OPT information stays in Check OPT. Employer browser verification is optional; use Verify now on a role.</p><p><strong id="summary-recorded">${state.jobs.length}</strong> recorded jobs · <strong id="summary-full">${full.length}</strong> active full descriptions · <strong id="summary-pending">${pending.length}</strong> leads to check for OPT · <strong id="summary-confirmed">${confirmed.length}</strong> roles with source-stated initial OPT acceptance.</p><p class="muted">${validated.length} roles have validated AI fit results. OPT acceptance in a listing does not approve your authorization or establish a strong fit, deadline or start date. FANG retains its separate preparation dashboard. Evidence quotes, sources and observation dates appear in each role.</p><div class="button-row"><button class="secondary" data-discovery-view="jobs">Open OPT-accepted roles</button><button class="secondary" data-discovery-view="verification">Check OPT</button><button class="secondary" data-discovery-view="discovery">Browse other roles</button><button class="secondary" data-research-reviews>View research fit reviews</button><button class="secondary" data-discovery-view="prepare">Open FANG dashboard</button></div></section>`}

function bindDiscoveryLinks(){document.querySelectorAll('[data-discovery-view]').forEach(b=>b.onclick=()=>setView(b.dataset.discoveryView));document.querySelectorAll('[data-research-reviews]').forEach(b=>b.onclick=()=>{setView('discovery');$('#tier-filter').value='research';$('#review-filter').value='complete';filterJobs()})}


// Research notes have their own freshness guard; they never approve local AI or visa policy.
const researchReviews=new WeakMap();
function canonicalResearchJSON(value){if(Array.isArray(value))return '['+value.map(canonicalResearchJSON).join(',')+']';if(value&&typeof value==='object')return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonicalResearchJSON(value[k])).join(',')+'}';return JSON.stringify(value)}
async function researchDigest(value){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value));return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function prepareResearchReviews(){const evidence=canonicalResearchJSON(state.profile.evidence||[]),profileDigest=await researchDigest(evidence);await Promise.all(state.jobs.filter(j=>j.manual_fit?.binding_version===1).map(async j=>{const review=j.manual_fit,valid=!!j.description_complete&&normalizedRoleURL(review.job_url)===normalizedRoleURL(j.url)&&review.profile_evidence_sha256===profileDigest&&review.description_sha256===await researchDigest(j.description||'')&&Number.isInteger(review.tier)&&review.tier>=1&&review.tier<=4&&Array.isArray(review.proofs)&&review.proofs.length>0&&Array.isArray(review.gaps);researchReviews.set(j,{valid,description:j.description,evidence,url:j.url,signature:canonicalResearchJSON(review)})}))}
function currentResearchReview(job){const cached=researchReviews.get(job),review=job.manual_fit,age=Date.now()-Date.parse(review?.reviewed_at||'');return cached?.valid&&cached.description===job.description&&cached.url===job.url&&cached.signature===canonicalResearchJSON(review)&&cached.evidence===canonicalResearchJSON(state.profile.evidence||[])&&Number.isFinite(age)&&age>=-300000&&age<=7*86400000?review:null}
function reviewOrder(job){const review=currentResearchReview(job);return review&&review.tier<=2&&job.screen.eligible&&!job.closed&&visaEvidence(job).status!=='conflict'?review.tier:currentFitTier(job)}
function jobSourceOptions(){const sources=new Map(state.sources.map(s=>[s.id,s.name]));for(const job of state.jobs){const id=sourceId(job);if(id&&!sources.has(id))sources.set(id,sourceName(job)||'Imported source')}return [...sources].map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}
function researchReviewPanel(job){const review=currentResearchReview(job);if(!review)return job.manual_fit?'<section class="detail-section"><h3>Research fit review needs rechecking</h3><p>The description, candidate proof, source identity or review date no longer matches the saved review. The previous notes remain available below.</p></section>':'';return `<section class="detail-section research-fit-review"><h3>Research fit review · ${job.screen.eligible?'Tier '+esc(review.tier):'Scope needs clarification'}</h3><p>${esc(review.rationale)}</p><p class="muted">Proof-based research notes; not validated local-model output. OPT, future sponsorship and start date are checked separately.</p><h4>Relevant candidate proof</h4><ul>${review.proofs.map(p=>`<li>${esc(p.claim)}${p.comparability?`<small>${esc(p.comparability)}</small>`:''}</li>`).join('')}</ul><h4>Gaps and questions</h4><ul>${review.gaps.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="muted">Reviewed ${esc(review.reviewed_at)}. Recheck the exact employer role before applying.</p></section>`}

function employerOriginChain(job,evidence){
const raw=evidence.origin_chain,chain=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{},corporate=safeLink(chain.corporate_careers_url),portal=safeLink(chain.official_hiring_portal_url),exact=safeLink(chain.exact_job_url),roleURL=normalizedRoleURL(job.url);const matches=!!roleURL&&normalizedRoleURL(exact)===roleURL,identity=(!evidence.job_id||evidence.job_id===job.id)&&(!evidence.job_url||normalizedRoleURL(evidence.job_url)===roleURL),checked=Date.parse(chain.checked_at||''),verified=chain.chain_verified===true&&!!corporate&&!!portal&&matches&&identity&&Number.isFinite(checked)&&checked<=Date.now()+300000;
const recordedURLs=new Set([corporate,portal,job.url,exact].filter(Boolean).map(normalizedRoleURL));const others=[...new Set((Array.isArray(evidence.sources)?evidence.sources:[]).map(x=>safeLink(typeof x==='string'?x:x?.url||x?.source_url)).filter(x=>x&&!recordedURLs.has(normalizedRoleURL(x))))];
const sourceLabel=url=>{try{const u=new URL(url);return /^(?:api\.|boards-api\.)/.test(u.hostname)||/\/(?:api|cxs)(?:\/|\?)/.test(u.pathname)?'Posting data API':'Additional employer evidence'}catch{return 'Additional employer evidence'}};
return `<section class="detail-section employer-origin-chain"><h3>Company website and posting sources</h3><p>${pill(verified?'Corporate-to-portal link checked for this role':'Corporate website chain not verified for this role',verified?'good':'warn')}</p><p><strong>Corporate careers page</strong><br>${corporate?link(corporate,'Open corporate careers page','small-button'):'Corporate careers page not checked.'}</p><p><strong>${verified?'Official hiring portal':'Recorded hiring portal (ownership unconfirmed for this role)'}</strong><br>${portal?link(portal,'Open hiring portal','small-button'):'No corporate-to-portal ownership record is available.'}</p><p><strong>Exact job posting</strong><br>${link(job.url,'Open this exact role','small-button')}</p>${exact&&!matches?'<p class="muted">The recorded website chain belongs to a different posting. It does not verify this role.</p>':''}${others.map(url=>`<p><strong>${sourceLabel(url)}</strong><br>${link(url,'Open posting evidence','small-button')}</p>`).join('')}${safeLink(chain.literal_link_href)?`<p class="muted">Recorded corporate link: ${link(chain.literal_link_href,chain.literal_link_label||'Hiring link on corporate careers page')}</p>`:''}<p class="muted">Website ownership checked: ${esc(String(chain.checked_at||'Not checked').slice(0,10))}. A corporate careers page linking to a hiring portal establishes portal ownership only. It does not verify OPT acceptance, future sponsorship, fit, deadline or your work authorization.</p></section>`;
}

function boardInformationBadge(job){const f=job.information_feedback;if(!f||!['correct','incorrect','unsure'].includes(f.verdict))return '';return pill('Your info report: '+f.verdict+' ('+(f.field||'other')+')',f.verdict==='incorrect'?'bad':'warn')}
function boardInformationPanel(job){const f=job.information_feedback||{},verdict=['correct','incorrect','unsure','cleared'].includes(f.verdict)?f.verdict:'unsure',field=['visa','deadline','location','salary','availability','other'].includes(f.field)?f.field:'other';return `<section class="detail-section board-information-feedback"><h3>Board-reported information & your feedback</h3><p>Recorded discovery source: <strong>${esc(sourceName(job))}</strong>. Source-reported details remain discovery information. Current role-specific posting or board wording is required for OPT-accepted leads. Future H-1B is optional.</p><p class="muted">${esc(job.availability||'Source availability not reported')}. Missing listing details: Check with employer. A hint or your feedback does not confirm OPT acceptance or future sponsorship.</p>${boardInformationBadge(job)}<div class="two-columns"><label>Your information report<select id="information-verdict"><option value="unsure" ${verdict==='unsure'?'selected':''}>Unsure / needs review</option><option value="correct" ${verdict==='correct'?'selected':''}>Looks correct</option><option value="incorrect" ${verdict==='incorrect'?'selected':''}>Incorrect information</option><option value="cleared" ${verdict==='cleared'?'selected':''}>Clear my report</option></select></label><label>Which detail? (optional)<select id="information-field">${[['other','Other / whole listing'],['visa','Visa / sponsorship'],['deadline','Deadline'],['location','Location'],['salary','Salary'],['availability','Availability']].map(([value,label])=>`<option value="${value}" ${field===value?'selected':''}>${label}</option>`).join('')}</select></label></div><label>What is wrong or what did you confirm?<textarea id="information-note" rows="3" maxlength="2000" placeholder="Optional note or source for your report">${esc(f.note||'')}</textarea></label><button id="save-information-feedback" class="secondary">Save board-information feedback</button><p class="muted">This is your report about the source information. Original employer evidence, job fit and application progress are retained. An active incorrect visa report removes this role from OPT-accepted leads until you clear or revise it; other fields do not change visa status.${job.information_feedback_at?' Saved '+esc(String(job.information_feedback_at).slice(0,10))+'.':''}</p></section>`}
function bindBoardInformationFeedback(job){$('#save-information-feedback').onclick=async()=>{try{const information_feedback={verdict:$('#information-verdict').value,field:$('#information-field').value,note:$('#information-note').value};await saveDetailUpdate(job,{information_feedback},['information-verdict','information-field','information-note']);message('Your board-information feedback was saved privately. Incorrect visa reports are held for review; original evidence and application progress are retained.')}catch(error){message(error.message,true)}}}


// Rolling verification uses the same sorted rows the user sees. Pagination does
// not expand the automatic window; later roles are an explicit Verify now action.
let verificationTimer,verificationPoll,verificationSignature='',verificationBusy=false;
const finishedApplicationStages=['Applied','Interview','Offer','Rejected','Archived'];
function currentBrowserVerification(j){const v=j.browser_verification;if(!v||v.job_id!==j.id||normalizedRoleURL(v.job_url)!==normalizedRoleURL(j.url))return null;if(state.verification_profile_version&&v.profile_version!==state.verification_profile_version)return null;return v}
function freshBrowserEvidence(j){const v=currentBrowserVerification(j);if(!v)return null;const age=Date.now()-Date.parse(v.source_observed_at||v.checked_at||v.completed_at);return age>=0&&age<7*86400000?v:null}
function browserHardConflict(j){const v=freshBrowserEvidence(j),e=v?.review?.eligibility;return v?.status==='closed'||visaEvidence(j).status==='conflict'||(e?.group==='incompatible'&&((e.graduation_conflicts||[]).length>0||(e.reasons||[]).some(x=>/citizen|clearance|graduat|enroll|location|initial OPT|not accept OPT/i.test(x))))}
function verificationActionable(j){return !finishedApplicationStages.includes(j.status)&&!j.closed&&j.screen.eligible&&j.source_feedback!=='not_interested'&&!browserHardConflict(j)}
function visaEvidence(job){
return window.OPTPolicy.evaluate(job);
}
function applicationEligibility(j){
const v=freshBrowserEvidence(j),e=v?.review?.eligibility||{},policy=visaEvidence(j),prefs={...state.profile?.preferences,...state.preferences};
const disputed=policy.status==='pending'&&(e.source_policy_conflict||e.identity_mismatch||j.information_feedback?.field==='visa'&&j.information_feedback?.verdict==='incorrect');
const checks=[],add=(id,label,status,detail,question='',evidence=[])=>checks.push({id,label,status,detail,question,evidence});
const proof=policy.initial_opt.evidence;
add('source','Role-specific listing evidence',proof.length?'stated':'unknown',proof.length?'Current quoted information from this job posting or board.':'No current role-specific OPT wording is recorded.',proof.length?'':'Check the listing or ask whether this role accepts initial OPT.');
for(const [id,label,field,question] of [
 ['opt','Employer accepts initial OPT','initial_opt','Does this exact role accept initial post-completion OPT?'],
 ['stem','STEM OPT extension (separate)','stem_opt','Does this role support a STEM OPT extension if needed?'],
 ['future','Future H-1B sponsorship (optional)','future_sponsorship','Does this role offer future H-1B sponsorship? This is optional for your current search.']
]){const dimension=policy[field],mandatory=id==='opt',value=dimension.value;add(id,label,disputed?'review':value==='accepted'?'stated':['excluded','conflict'].includes(value)?mandatory?'conflict':'optional':'unknown',disputed?'Source claims are disputed; confirmation is withheld.':value==='unknown'?'Not stated; check with employer.':value==='excluded'&&!mandatory?'Not offered; this does not exclude initial OPT roles.':value==='accepted'?'Acceptance stated in current role-specific listing evidence.':value,value==='accepted'||!mandatory?'':question,dimension.evidence.map(x=>({quote:x.quote,url:x.source_url,observed_at:x.observed_at,source:x.source})))}
const authorization=prefs.workAuthorization||'Not recorded',start=prefs.fullTimeStart||'Not recorded';
add('authorization','Your work authorization','review',authorization,'Confirm your actual authorization status and permitted employment dates; a planned OPT application is insufficient.');
add('start','Authorized start date vs role start','review',`Your recorded start: ${start}. Employer start: ${v?.review?.additional_checks?.start_date||'not stated'}.`,'Confirm the required role start and whether it falls within your authorized employment dates.');
const graduation=e.graduation_conflicts||[];
add('restrictions','Graduation / other eligibility restrictions',graduation.length||browserHardConflict(j)?'conflict':'review',graduation.length?graduation.map(x=>x.reason).join(' · '):e.group==='incompatible'?(e.reasons||[]).join(' · '):`Saved graduation: ${state.preferences?.graduation||state.profile?.education?.graduation||'not recorded'}. Not all role restrictions have been checked.`,graduation.length||browserHardConflict(j)?'Resolve the published restriction before proceeding.':'Check graduation, citizenship, clearance and other mandatory restrictions on this exact role.',graduation.map(x=>({quote:x.quote,url:x.url})));
const conflict=policy.status==='conflict'||checks.some(x=>x.status==='conflict')||j.closed||v?.role_status==='closed',unresolved=checks.filter(x=>['conflict','unknown','review'].includes(x.status));
return {status:conflict?'conflict':'needs_confirmation',label:conflict?'Eligibility conflict — resolve before applying':policy.status==='confirmed'?'OPT accepted · your authorization needs confirmation':'Check OPT · your eligibility needs confirmation',checks,questions:unresolved.filter(x=>x.question).map(x=>x.question)};
}
function applicationEligibilityCard(j){const a=applicationEligibility(j),next=a.checks.find(x=>['conflict','unknown','review'].includes(x.status));return `<p class="eligibility-card"><strong>${esc(a.label)}</strong>${next?`<br>${esc(next.label)}: ${esc(next.detail)}`:''}</p>`}
function applicationEligibilityPanel(j){const a=applicationEligibility(j);return `<section class="application-eligibility" aria-label="Your application eligibility"><h4>${esc(a.label)}</h4><p>Employer policy and your authorization are separate. Reading a page or getting a strong skills tier does not complete these checks.</p><div class="table-wrap"><table><thead><tr><th>Check</th><th>Result and evidence</th></tr></thead><tbody>${a.checks.map(x=>`<tr><th scope="row">${esc(x.label)}</th><td>${pill(x.status==='stated'?'Stated':x.status==='conflict'?'Conflict':x.status==='unknown'?'Unknown':x.status==='optional'?'Optional / not offered':'Needs confirmation',x.status==='stated'?'good':x.status==='conflict'?'bad':'warn')}<p>${esc(x.detail)}</p>${x.evidence.map(z=>`<blockquote>${esc(z.quote)} ${z.url?link(z.url,'Listing source ↗'):''}<small> ${esc(z.source||'Listing')} · Observed ${esc(z.observed_at||'unknown')}</small></blockquote>`).join('')}</td></tr>`).join('')}</tbody></table></div>${a.questions.length?`<details><summary>Questions to resolve before applying (${a.questions.length})</summary><ol>${a.questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></details>`:''}</section>`}
function verificationPriority(j){const policy=visaEvidence(j);return policy.status==='confirmed'?0:policy.status==='conflict'?3:policy.initial_opt.evidence.length?1:2}

function browserAccessPriority(j){const v=currentBrowserVerification(j),age=Date.now()-Date.parse(v?.completed_at||v?.checked_at||'');return v&&['needs_capture','error'].includes(v.status)&&age>=0&&age<86400000?1:0}
function verificationOrder(a,b){return browserAccessPriority(a)-browserAccessPriority(b)||verificationPriority(a)-verificationPriority(b)||reviewOrder(a)-reviewOrder(b)||b.contacts_count-a.contacts_count||String(b.first_seen).localeCompare(String(a.first_seen))||a.id.localeCompare(b.id)}
function verificationJob(j){return Object.fromEntries(['id','url','title','company','location','board_url','employment_type','salary','status','closed','source_feedback'].map(k=>[k,k==='salary'&&typeof j[k]==='object'?JSON.stringify(j[k]):j[k]??'']))}
function verificationBody(extra){return {...extra,profile:state.profile,preferences:state.preferences}}
function mergeVerification(data){state.verification_profile_version=data.profile_version;for(const v of data.entries||[]){const j=state.jobs.find(x=>x.id===v.job_id);if(j&&normalizedRoleURL(j.url)===normalizedRoleURL(v.job_url))j.browser_verification=v}state.verification_queue=data;updateVerificationQueue()}
function updateVerificationQueue(){const el=$('#verification-queue');if(!el)return;const q=state.verification_queue,entries=q?.entries||[],running=entries.filter(v=>['queued','running'].includes(v.status)).length;el.textContent='Employer browser checks are optional. Use Verify now on a role.'+(running?' '+running+' manually requested checks queued/running.':'')}

function scheduleVerification(rows){clearTimeout(verificationTimer);updateVerificationQueue()}

function startVerificationPolling(){if(verificationPoll)return;verificationPoll=setInterval(async()=>{if(!state||verificationBusy)return;try{mergeVerification(await api('/api/verification-status',verificationBody({ids:state.jobs.map(j=>j.id)})));if(['jobs','prepare','quick','discovery','verification'].includes(view))filterJobs();if(activeJob){activeJob=state.jobs.find(j=>j.id===activeJob.id)||activeJob;const panel=$('#browser-verification-panel');if(panel){const questionsOpen=!!panel.querySelector('.application-eligibility details[open]');panel.outerHTML=browserVerificationPanel(activeJob);if(questionsOpen)$('#browser-verification-panel .application-eligibility details')?.setAttribute('open','')}}}catch(e){const el=$('#verification-queue');if(el)el.textContent='Verification paused: '+e.message}},5000)}
async function verifyBrowserNow(id){try{const j=state.jobs.find(x=>x.id===id);if(!j)return;mergeVerification(await api('/api/verification-demand',verificationBody({job:verificationJob(j)})));startVerificationPolling();message('Queued for local browser verification. Results update automatically.');filterJobs()}catch(e){message(e.message,true)}}
function browserVerificationBadge(j){const v=currentBrowserVerification(j);if(!v)return pill('Browser check optional','warn');const labels={queued:'Verification queued',running:'Verifying locally',verified:'Page evidence verified',needs_capture:'Needs browser capture',conflict:'Verification conflict',closed:'Employer posting closed',error:'Verification needs retry'};const stale=['verified','conflict','closed'].includes(v.status)&&!freshBrowserEvidence(j);return pill(stale?'Evidence expired: verify again':labels[v.status]||'Needs review',v.status==='verified'&&!stale?'good':'warn')}
function fitReviewReason(fit){const reason=fit?.note||fit?.reason||'';if(/fetch failed|ECONNREFUSED|Unable to connect/i.test(reason))return 'The local model runtime was unreachable. Run start-dashboard.ps1, then retry this role. Page evidence remains available.';if(/Literal technical requirements and candidate evidence/.test(reason))return 'The posting did not yield source-backed technical requirements to score. Review the full description; no fit tier was generated.';if(/Traceback|ValueError|site-packages|[A-Z]:\\/i.test(reason))return 'The local skills review could not complete its evidence checks. Retry on demand or review the requirements manually.';return reason}
function browserVerificationPanel(j){const v=currentBrowserVerification(j),r=v?.review;return `<section id="browser-verification-panel" class="detail-section"><h3>Browser verification · eligibility first</h3>${browserVerificationBadge(j)}${applicationEligibilityPanel(j)}<p>${esc(v?.note||'Employer browser verification is optional. Use Verify now when you want a deeper check.')}</p>${v?.enrichment_note?`<p class="muted">${esc(v.enrichment_note)}</p>`:''}${v?.report_url?link(v.report_url,'Open evidence, screenshots & full report ↗','small-button'):''}${r?`<p><strong>Sponsorship / eligibility:</strong> ${esc(r.eligibility?.label||'Needs confirmation')}. Individual eligibility: ${esc(r.eligibility?.individual_eligibility||'not determined')}.</p><p>${esc((r.eligibility?.reasons||[]).join(' · '))}</p>${(r.sources||[]).map(x=>`<p><strong>${x.kind==='board'?'Job board':'Employer'} (${esc(x.status)}):</strong> Initial OPT: ${esc(x.sponsorship?.initial_opt||'not stated')}; future sponsorship: ${esc(x.sponsorship?.future_sponsorship||'not stated')}. ${x.url?link(x.url,'Source ↗'):''}</p>`).join('')}<p><strong>Posting dates:</strong> Board: ${esc((r.posting_dates?.board||[]).map(x=>x.value+' ('+x.kind+')').join(', ')||'not published / not captured')}; employer: ${esc((r.posting_dates?.employer||[]).map(x=>x.value+' ('+x.kind+')').join(', ')||'not published / not captured')}. ${esc(r.posting_dates?.comparison||'')}</p><p><strong>Application end date:</strong> ${esc((r.deadline?.records||[]).map(x=>x.value||x.evidence||JSON.stringify(x)).join(' · ')||r.deadline?.status||'not stated')}. ${esc(r.deadline?.note||'')}</p><p><strong>Laya skills review:</strong> ${esc(v.enrichment_status==='queued'||v.enrichment_status==='running'?'Queued/running after page checks':r.fit?.status||'unavailable')}${r.fit?.assessment?' · Advisory Tier '+esc(r.fit.assessment.tier):''}. ${esc(fitReviewReason(r.fit))}</p>${r.fit?.assessment?`<p>${esc(r.fit.assessment.verdict||'')}</p><ul>${(r.fit.assessment.gaps||[]).map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`:''}<p class="muted">Observed: ${esc(v.source_observed_at||v.checked_at||'unknown')}. Verified page evidence does not establish sponsorship eligibility. Local model calls: ${esc(v.local_model_calls||0)}; cloud model calls: ${esc(v.cloud_model_calls||0)}.</p>`:''}${['needs_capture','error'].includes(v?.status)?`<p>Open the exact posting in your normal Chrome session, capture it with the verifier extension, then click Verify this job now. ${link('http://127.0.0.1:8776/','Open local capture setup ↗')}</p>`:''}</section>`}
